WITH q AS (SELECT pu_zone, pu_borough, COUNT(*) AS trips, AVG(total_amount) AS avg_total_usd, SUM(total_amount) / SUM(trip_duration_minutes) * 60 AS avg_revenue_per_hour_usd, AVG(trip_distance_miles) AS avg_trip_miles, AVG(trip_duration_minutes) AS avg_duration_min FROM tlc.taxi.yellow_trips WHERE data_month IN (DATE '2026-01-01', DATE '2026-02-01', DATE '2026-03-01') AND pu_zone IS NOT NULL AND total_amount > 0 AND trip_duration_minutes > 0 GROUP BY pu_zone, pu_borough), tot AS (SELECT COUNT(*) AS all_trips FROM tlc.taxi.yellow_trips WHERE data_month IN (DATE '2026-01-01', DATE '2026-02-01', DATE '2026-03-01') AND pu_zone IS NOT NULL AND total_amount > 0 AND trip_duration_minutes > 0) SELECT q.pu_zone AS pu_zone, q.pu_borough AS pu_borough, q.trips AS trips, q.avg_total_usd AS avg_total_usd, q.avg_revenue_per_hour_usd AS avg_revenue_per_hour_usd, q.avg_trip_miles AS avg_trip_miles, q.avg_duration_min AS avg_duration_min, q.trips * 100.0 / tot.all_trips AS share_trips_pct FROM q CROSS JOIN tot WHERE q.trips >= 1000 ORDER BY q.avg_total_usd DESC, q.pu_zone LIMIT 12
